import{a as e,f as t,g as n,h as r,l as i,p as a,s as o,t as s,u as c,v as l}from"./index-CLFXDBE0.js";var u={class:`card`},d=s(a({__name:`CATAView`,setup(a){let s=l([{img:new URL(`/assets/Report%20pg%201-CZZDI2CQ.png`,``+import.meta.url).href,alt:`Report page 1. Shows the front page of the report for Thornfield Academy, a fictional school.`},{img:new URL(`/assets/Report%20pg%202-B8Ik0yyj.png`,``+import.meta.url).href,alt:`Report page 2. Shows an overview of the CATA audit and how it works.`},{img:new URL(`/assets/Report%20pg%203-CtU7NHaD.png`,``+import.meta.url).href,alt:`Report page 3. Shows an overview of the school's alignment and priority actions.`},{img:new URL(`/assets/Report%20pg%204-EmS9IqMJ.png`,``+import.meta.url).href,alt:`Report page 4. Shows the audit dashboard.`},{img:new URL(`/assets/Report%20pg%205-ChrCOOAz.png`,``+import.meta.url).href,alt:`Report page 5. Shows a more detailed breakdown of the assessment for Curriculum, Teaching and Learning, and Assessment.`},{img:new URL(`/assets/Report%20pg%206-BFJXbX5S.png`,``+import.meta.url).href,alt:`Report page 6. Shows a more detailed breakdown of the assessment for Data Systems, Timetable and Governance.`},{img:new URL(`/assets/Report%20pg%207-DWFkY4mN.png`,``+import.meta.url).href,alt:`Report page 7. Shows the breakpoints.`},{img:new URL(`/assets/Report%20pg%208-DQCp1UaW.png`,``+import.meta.url).href,alt:`Report page 8. Shows the suggested action plan for improving alignment.`},{img:new URL(`/assets/Report%20pg%209-CCxiQZPo.png`,``+import.meta.url).href,alt:`Report page 9. Shows key themes and next steps.`}]);return(a,l)=>{let d=n(`SimpleCarousel`),f=n(`KnowMore`);return r(),i(e,null,[l[3]||=c(`<section data-v-bffb232f><div class="section-label" data-v-bffb232f> Curriculum, Assessment, Teaching Alignment Framework </div><h1 data-v-bffb232f>CATA: A Framework for Building High-Performing Teams</h1><p data-v-bffb232f>CATA is the diagnostic backbone of Alygn Education. It gives you a structured way to see where your systems are working together — and where they’re quietly working against each other. Most organisations don’t have a quality problem; they have an alignment problem.</p></section><section data-v-bffb232f><div class="card" data-v-bffb232f><span class="section-label" data-v-bffb232f>What CATA is</span><div class="two-col" data-v-bffb232f><div data-v-bffb232f><h2 data-v-bffb232f>Six domains, one alignment question.</h2><p data-v-bffb232f>The core idea is simple: it’s not just the quality of each domain that matters — it’s the quality of alignment between them. Misalignment is where workload, confusion and inconsistency creep in.</p><p data-v-bffb232f>CATA looks at six domains that shape the experience of learners and staff:</p></div><div data-v-bffb232f><h2 data-v-bffb232f>Good people can’t fix bad systems.</h2><p data-v-bffb232f>When curriculum says one thing, assessment measures another, data reports something else and the timetable quietly undermines everything, even the best staff end up firefighting.</p><p data-v-bffb232f>CATA exposes the hidden breakpoints so you can fix the system, not the symptoms.</p></div></div><div class="card allignment-card" data-v-bffb232f><img alt="Allignment model" src="/assets/allignment-model-CeX321Hr.png" class="allignment-img" data-v-bffb232f></div></div></section><section data-v-bffb232f><div class="section-label" data-v-bffb232f> How it works </div><h2 data-v-bffb232f>The CATA Audit Process</h2><div class="two-col" style="margin-top:1.5rem;" data-v-bffb232f><div class="card" data-v-bffb232f><span class="pill" data-v-bffb232f>1. Pre-audit</span><h3 data-v-bffb232f>Scoping and document review</h3><p data-v-bffb232f>A short scoping call to understand your context, followed by a review of key documents:</p><ul class="list-plain" data-v-bffb232f><li data-v-bffb232f>Curriculum plans</li><li data-v-bffb232f>Timetables</li><li data-v-bffb232f>Assessment policies</li><li data-v-bffb232f>Data reports</li><li data-v-bffb232f>Governance papers</li></ul></div><div class="card" data-v-bffb232f><span class="pill" data-v-bffb232f>2. Audit</span><h3 data-v-bffb232f>Interviews, evidence and scoring</h3><p data-v-bffb232f>Conversations with leaders and staff, review of systems and documentation, and scoring across all domains.</p><p data-v-bffb232f>The focus is on alignment — where systems support each other, and where they quietly pull in different directions.</p></div></div><div class="two-col" style="margin-top:1.5rem;" data-v-bffb232f><div class="card" data-v-bffb232f><span class="pill" data-v-bffb232f>3. Reporting</span><h3 data-v-bffb232f>Your alignment map</h3><p data-v-bffb232f>You receive a full alignment report including:</p><ul class="list-plain" data-v-bffb232f><li data-v-bffb232f>Domain scores and narrative</li><li data-v-bffb232f>Cross-domain breakpoints</li><li data-v-bffb232f>Key themes and risks</li><li data-v-bffb232f>A sequenced action plan</li></ul><p data-v-bffb232f>It’s clear, honest and practical — no jargon, no padding.</p></div><div class="card" data-v-bffb232f><span class="pill" data-v-bffb232f>4. Follow-up</span><h3 data-v-bffb232f>Turning insight into action</h3><p data-v-bffb232f>We walk through the report together and agree what you’ll tackle first. Some organisations take it from there; others ask for support with curriculum, timetable, assessment or AI work.</p><p data-v-bffb232f>Either way, you leave with clarity.</p></div></div></section>`,3),o(`section`,null,[o(`div`,u,[l[0]||=o(`span`,{class:`section-label`},`Sample report`,-1),l[1]||=o(`h2`,null,`See what this looks like in practice`,-1),l[2]||=o(`p`,null,`The sample report shows how each domain is scored, where misalignment is doing the most damage, what’s working well and should be protected, and a realistic set of next steps. Please note that this report is fictitious.`,-1),t(d,{images:s.value,"max-height":`550px`},null,8,[`images`])])]),t(f)],64)}}}),[[`__scopeId`,`data-v-bffb232f`]]);export{d as default};